<template><main class="page"><h1>Two-factor verification</h1><p>Enter an authenticator code or a one-time backup code.</p><label>Code <input v-model="code" autocomplete="one-time-code" /></label><button :disabled="busy || !code" @click="verifyTotp">Verify authenticator code</button><button :disabled="busy || !code" @click="verifyBackup">Use backup code</button><p v-if="error" class="error">{{ error }}</p></main></template>
<script setup lang="ts">import{ref}from"vue";import{useRouter}from"vue-router";import{authClient}from"../auth/client";import{refreshAuthFromSession}from"../services/auth/sessionBootstrap";import{registerPrivilegedAdminStepUp}from"../services/privilegedStepUpService";import{getAuthState,setSecondaryAuth}from"../store/authState";const router=useRouter(),code=ref(""),error=ref(""),busy=ref(false);const run=async(kind:"totp"|"backup")=>{busy.value=true;error.value="";const result=kind==="totp"?await authClient.twoFactor.verifyTotp({code:code.value,trustDevice:false}):await authClient.twoFactor.verifyBackupCode({code:code.value,trustDevice:false});busy.value=false;if(result.error){error.value=result.error.message??"Verification failed.";return;}await refreshAuthFromSession();const auth=getAuthState();if(auth.role==="super_admin"){await registerPrivilegedAdminStepUp();setSecondaryAuth(true);}await router.replace(auth.role==="super_admin"?"/super-admin":"/");};const verifyTotp=()=>run("totp");const verifyBackup=()=>run("backup");</script>
